mapper.select:
SELECT wo.id, wo.user_id as userId, u.mobile, wo.username, u.channel, wo.msg, wo.withdraw_time as withdrawTime, wo.amount, wo.inputamount, wo.rate, wo.hand_fee as handFee, wo.real_amount as realAmount, wo.channel_amount as channelAmount, wo.blank_code as blankCode, wo.blank_name as blankName, wo.pay_name as payName, wo.pay_no as payNo, wo.oper_code as operCode, wo.remark, wo.create_time as createTime, wo.state_time as stateTime, wo.state, wo.withdraw_type as withdrawType, wo.part_mon as partMon, wo.orderno, wo.threeorder_no as threeorderNo, wo.sourcetype_name as sourcetypeName, wo.info_ip as infoIp, wo.ifsc, wo.agent_name as agentName, wo.agent, wo.salesmanid, wo.salesman_name as salesmanName, wo.channelid, wo.merchantid, pm.merchantname, wo.biaoqian, wo.invite_code_status as inviteCodeStatus, wo.liebian, wo.ctc, u.agent as userAgent, u.salesmanid as userSalesmanid, salesman_user.username as salesmanName FROM tb_withdraw_order wo LEFT JOIN tb_user u ON wo.user_id = u.id LEFT JOIN sys_user salesman_user ON u.salesmanid = salesman_user.id LEFT JOIN pay_merchant pm ON pm.merchantid=wo.merchantid
AND wo.create_time >= FROM_UNIXTIME(#{params.startTime} / 1000)
AND wo.create_time <= FROM_UNIXTIME(#{params.endTime} / 1000)
AND wo.orderno LIKE CONCAT('%', #{params.orderno}, '%')
AND wo.pay_no LIKE CONCAT('%', #{params.pay_no}, '%')
AND wo.state = #{params.state}
AND wo.threeorder_no LIKE CONCAT('%', #{params.threeorder_no}, '%')
AND wo.withdraw_type = #{params.withdraw_type}
AND wo.mobile LIKE CONCAT('%', #{params.mobile}, '%')
AND wo.username LIKE CONCAT('%', #{params.username}, '%')
AND u.agent = #{params.agent}
AND u.salesmanid = #{params.salesmanid}
AND wo.biaoqian LIKE CONCAT('%', #{params.biaoqian}, '%')
AND u.superior_name IS NOT NULL AND u.superior_name != ''
AND (u.superior_name IS NULL OR u.superior_name = '')
AND u.agent = #{params.currentUserId}
AND u.salesmanid = #{params.currentUserId}
ORDER BY wo.${params.orderField} ${params.order}
ORDER BY wo.create_time DESC

SELECT COALESCE(SUM(wo.inputamount), 0) AS amount, COALESCE(SUM(wo.real_amount), 0) AS realAmount, COALESCE(SUM(wo.channel_amount), 0) AS channelAmount, COALESCE(SUM(wo.hand_fee), 0) AS handFee, COUNT(*) AS totalCount FROM tb_withdraw_order wo LEFT JOIN tb_user u ON wo.user_id = u.id LEFT JOIN sys_user agent_user ON u.agent = agent_user.id LEFT JOIN sys_user salesman_user ON u.salesmanid = salesman_user.id
AND wo.create_time >= FROM_UNIXTIME(#{params.startTime} / 1000)
AND wo.create_time <= FROM_UNIXTIME(#{params.endTime} / 1000)
AND wo.orderno LIKE CONCAT('%', #{params.orderno}, '%')
AND wo.pay_no LIKE CONCAT('%', #{params.pay_no}, '%')
AND wo.state = #{params.state}
AND wo.threeorder_no LIKE CONCAT('%', #{params.threeorder_no}, '%')
AND wo.withdraw_type = #{params.withdraw_type}
AND wo.mobile LIKE CONCAT('%', #{params.mobile}, '%')
AND wo.username LIKE CONCAT('%', #{params.username}, '%')
AND u.agent = #{params.agent}
AND u.salesmanid = #{params.salesmanid}
AND wo.biaoqian LIKE CONCAT('%', #{params.biaoqian}, '%')
AND u.superior_name IS NOT NULL AND u.superior_name != ''
AND (u.superior_name IS NULL OR u.superior_name = '')
AND u.agent = #{params.currentUserId}
AND u.salesmanid = #{params.currentUserId}
